// Get all posts from the WordPress node
const posts = $input.all();

// Calculate the date 6 months ago
const now = new Date();
const sixMonthsAgo = new Date(now);
sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);

// Filter posts not modified in the last 6 months
const stalePosts = posts.filter(item => {
  const modified = new Date(item.json.modified);
  return modified < sixMonthsAgo;
});

// Sort by oldest first
stalePosts.sort((a, b) => new Date(a.json.modified) - new Date(b.json.modified));

// Build a summary for each stale post
const results = stalePosts.map(item => {
  const modified = new Date(item.json.modified);
  const daysSince = Math.floor((now - modified) / (1000 * 60 * 60 * 24));
  return {
    title: item.json.title?.rendered || item.json.title || 'Untitled',
    url: item.json.link || '',
    last_modified: modified.toISOString().split('T')[0],
    days_since_update: daysSince,
    post_id: item.json.id
  };
});

// If no stale posts, return a flag so the IF node can stop the flow
if (results.length === 0) {
  return [{ json: { stale_count: 0, message: 'All blogs are up to date!' } }];
}

// Build the Slack message
let slackMessage = `🔴 *Stale Blog Alert* — ${results.length} blog(s) haven't been updated in 6+ months:\n\n`;

results.forEach((post, i) => {
  slackMessage += `*${i + 1}. ${post.title}*\n`;
  slackMessage += `   Last modified: ${post.last_modified} (${post.days_since_update} days ago)\n`;
  slackMessage += `   ${post.url}\n\n`;
});

slackMessage += `_Run date: ${now.toISOString().split('T')[0]}_`;

return [{ json: { stale_count: results.length, slack_message: slackMessage, stale_posts: results } }];
